package app.scapestack.runelite;

import org.junit.Test;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.*;

/**
 * Tests the DiaryReader path that converts var-values into
 * DiaryCompletion records. We feed the reader a mock value-source so
 * we never construct a RuneLite Client — the same pattern QuestHelper
 * tests use for its diary plugins.
 */
public class DiaryReaderTest {

    /**
     * The simplest case: a maxed-ish account with every varbit set
     * to 1 and every Karamja varplayer past its milestone. We expect
     * all 48 tiers (12 regions × 4) to come back as complete.
     */
    @Test
    public void readsAllCompleteWhenAllVarsSet() {
        DiaryReader reader = new DiaryReader();
        List<GameStateReader.DiaryCompletion> result = reader.readFrom(
            (id) -> 999, // legacy reader; not used by the entryReader path
            (entry) -> entry.isVarbit ? 1 : 999 // any 'past milestone' value
        );
        assertEquals("12 regions × 4 tiers", DiaryVarTable.ENTRIES.size(), result.size());
        // Sample: Karamja Easy should be in there
        assertTrue(result.stream().anyMatch(d -> "Karamja".equals(d.region) && "Easy".equals(d.tier)));
    }

    /**
     * Empty account — no varbits set, no Karamja milestones. We expect
     * zero completions.
     */
    @Test
    public void readsZeroCompleteWhenAllVarsAreZero() {
        DiaryReader reader = new DiaryReader();
        List<GameStateReader.DiaryCompletion> result = reader.readFrom(
            (id) -> 0,
            (entry) -> 0
        );
        assertTrue("zero complete when all vars zero", result.isEmpty());
    }

    /**
     * Mixed account: Karamja Hard done, Falador Easy done, nothing else.
     * Verifies that we don't bleed completions across regions/tiers.
     */
    @Test
    public void readsMixedCompletionsCorrectly() {
        // Build a small map of var-id → observed value
        Map<Integer, Integer> mockVars = new HashMap<>();
        // Karamja Hard: varplayer 3611, milestone 5
        mockVars.put(3611, 5);
        // Falador Easy: varbit 4504, completed = 1
        mockVars.put(4504, 1);

        DiaryReader reader = new DiaryReader();
        List<GameStateReader.DiaryCompletion> result = reader.readFrom(
            (id) -> mockVars.getOrDefault(id, 0),
            (entry) -> mockVars.getOrDefault(entry.varbitOrVar, 0)
        );

        assertEquals(2, result.size());
        assertTrue(result.stream().anyMatch(d -> "Karamja".equals(d.region) && "Hard".equals(d.tier)));
        assertTrue(result.stream().anyMatch(d -> "Falador".equals(d.region) && "Easy".equals(d.tier)));
        // Negative checks: things that should NOT be present
        assertFalse(result.stream().anyMatch(d -> "Karamja".equals(d.region) && "Elite".equals(d.tier)));
        assertFalse(result.stream().anyMatch(d -> "Wilderness".equals(d.region)));
    }

    /**
     * The Karamja varplayer is unusual: it counts up through milestones
     * rather than flipping to 1. A value below the completion threshold
     * should NOT mark the tier as done.
     */
    @Test
    public void karamjaVarplayerHonoursMilestoneThreshold() {
        Map<Integer, Integer> mockVars = new HashMap<>();
        // Karamja Easy completion-value is 5; supply 4 (one short)
        mockVars.put(3578, 4);

        DiaryReader reader = new DiaryReader();
        List<GameStateReader.DiaryCompletion> result = reader.readFrom(
            (id) -> mockVars.getOrDefault(id, 0),
            (entry) -> mockVars.getOrDefault(entry.varbitOrVar, 0)
        );

        assertFalse("Karamja Easy at 4 should NOT be marked done",
            result.stream().anyMatch(d -> "Karamja".equals(d.region) && "Easy".equals(d.tier)));

        // Now bump to 5 — should flip to done
        mockVars.put(3578, 5);
        result = reader.readFrom(
            (id) -> mockVars.getOrDefault(id, 0),
            (entry) -> mockVars.getOrDefault(entry.varbitOrVar, 0)
        );
        assertTrue("Karamja Easy at 5 should be marked done",
            result.stream().anyMatch(d -> "Karamja".equals(d.region) && "Easy".equals(d.tier)));
    }

    /**
     * A bad var read (e.g. id removed from the game) should be skipped
     * silently, not crash the whole sync. We simulate this by throwing
     * from the entry reader for one specific entry and confirming the
     * rest still come back.
     */
    @Test
    public void singleBadVarDoesNotKillTheSync() {
        DiaryReader reader = new DiaryReader();
        List<GameStateReader.DiaryCompletion> result = reader.readFrom(
            (id) -> 1,
            (entry) -> {
                if (entry.varbitOrVar == 4458) {
                    throw new RuntimeException("simulated bad var read");
                }
                return entry.isVarbit ? 1 : 999;
            }
        );
        // 1 entry skipped, the other 47 should still be there
        assertEquals(DiaryVarTable.ENTRIES.size() - 1, result.size());
    }
}

package app.scapestack.runelite;

import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PairingClientTest {
    @Test
    public void approvesCodeWithInstallTokenOutsideJsonBody() {
        final String[] url = new String[1];
        final String[] authorization = new String[1];
        final String[] body = new String[1];
        OkHttpClient http = new OkHttpClient.Builder()
            .addInterceptor(chain -> {
                url[0] = chain.request().url().toString();
                authorization[0] = chain.request().header("Authorization");
                Buffer buffer = new Buffer();
                chain.request().body().writeTo(buffer);
                body[0] = buffer.readUtf8();
                return new Response.Builder()
                    .request(chain.request())
                    .protocol(Protocol.HTTP_1_1)
                    .code(200)
                    .message("OK")
                    .body(ResponseBody.create(MediaType.parse("application/json"), "{\"ok\":true}"))
                    .build();
            })
            .build();

        PairingClient client = new PairingClient(http);
        assertTrue(client.approve(
            "https://www.scapestack.org/api/sync",
            "Lynx Titan",
            "abcd-efgh",
            "11111111-2222-3333-4444-555555555555",
            "scapestack-test"
        ));
        assertEquals("https://www.scapestack.org/api/account/pair/approve", url[0]);
        assertEquals("Bearer 11111111-2222-3333-4444-555555555555", authorization[0]);
        assertTrue(body[0].contains("\"code\":\"ABCDEFGH\""));
        assertFalse(body[0].contains("token"));
    }

    @Test
    public void derivesProductionAndLocalPairingUrls() {
        assertEquals(
            "https://www.scapestack.org/api/account/pair/approve",
            PairingClient.pairingUrlFromSyncUrl("https://www.scapestack.org/api/sync")
        );
        assertEquals(
            "http://127.0.0.1:4173/api/account/pair/approve",
            PairingClient.pairingUrlFromSyncUrl("http://127.0.0.1:4173/api/sync")
        );
    }
}

package app.scapestack.runelite;

import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BossKillCountReaderTest {
    private static final String CAPTURED_AT = "2026-07-18T12:34:56Z";

    @Test
    public void readsOnlyObservedCountsAndPreservesExplicitZero() {
        Map<String, Integer> cache = new HashMap<>();
        cache.put("vorkath", 48);
        cache.put("zulrah", 0);

        BossKillCountReader.Result result = BossKillCountReader.readObservedCounts(
            Arrays.asList("Vorkath", "Zulrah", "Callisto"),
            cache::get,
            CAPTURED_AT
        );

        assertTrue(result.isAvailable());
        assertEquals(3, result.catalogBosses);
        assertEquals(2, result.knownBosses);
        assertEquals(Integer.valueOf(48), result.counts.get("Vorkath"));
        assertEquals(Integer.valueOf(0), result.counts.get("Zulrah"));
        assertFalse(result.counts.containsKey("Callisto"));
        assertEquals("runelite-killcount-cache-observed-only", result.reason);
    }

    @Test
    public void emptyCacheIsNotLoadedInsteadOfZeroKc() {
        BossKillCountReader.Result result = BossKillCountReader.readObservedCounts(
            Arrays.asList("Vorkath", "Zulrah"),
            key -> null,
            CAPTURED_AT
        );

        assertEquals("not-loaded", result.state);
        assertFalse(result.isAvailable());
        assertTrue(result.counts.isEmpty());
        assertEquals("boss-kill-log-not-observed", result.reason);
        assertNull(result.capturedAt);
    }

    @Test
    public void lookupFailureDoesNotTurnUnknownIntoZero() {
        BossKillCountReader.Result result = BossKillCountReader.readObservedCounts(
            Arrays.asList("Vorkath", "Zulrah"),
            key -> {
                if ("vorkath".equals(key)) return 48;
                throw new IllegalStateException("profile unavailable");
            },
            CAPTURED_AT
        );

        assertTrue(result.isAvailable());
        assertEquals(1, result.knownBosses);
        assertEquals(Integer.valueOf(48), result.counts.get("Vorkath"));
        assertFalse(result.counts.containsKey("Zulrah"));
        assertEquals("runelite-killcount-cache-partial", result.reason);
    }

    @Test
    public void allLookupFailuresAreUnavailable() {
        BossKillCountReader.Result result = BossKillCountReader.readObservedCounts(
            Arrays.asList("Vorkath", "Zulrah"),
            key -> { throw new IllegalStateException("profile unavailable"); },
            CAPTURED_AT
        );

        assertEquals("unavailable", result.state);
        assertEquals("boss-killcount-cache-unavailable", result.reason);
        assertTrue(result.counts.isEmpty());
    }

    @Test
    public void catalogIsNormalizedDeduplicatedAndBounded() {
        List<String> names = new ArrayList<>();
        names.add(" Vorkath ");
        names.add("vorkath");
        names.add("");
        for (int index = 0; index < 200; index++) names.add("Boss " + index);

        BossKillCountReader.Result result = BossKillCountReader.readObservedCounts(
            names,
            key -> 1,
            CAPTURED_AT
        );

        assertEquals(BossKillCountReader.MAX_BOSSES, result.catalogBosses);
        assertEquals(BossKillCountReader.MAX_BOSSES, result.knownBosses);
        assertEquals(Integer.valueOf(1), result.counts.get("Vorkath"));
    }

    @Test
    public void pinnedRuneLiteCatalogContainsOnlyBoundedBossRows() {
        List<String> catalog = BossKillCountReader.defaultBossCatalog();

        assertTrue(catalog.size() > 50);
        assertTrue(catalog.size() <= BossKillCountReader.MAX_BOSSES);
        assertTrue(catalog.contains("Vorkath"));
        assertTrue(catalog.contains("Zulrah"));
        assertFalse(catalog.contains("Clue Scrolls (all)"));
        assertFalse(catalog.contains("Last Man Standing"));
    }
}

package app.scapestack.runelite;

import org.junit.Test;

import java.util.List;

import static app.scapestack.runelite.CollectionLogReader.MockWidget.container;
import static app.scapestack.runelite.CollectionLogReader.MockWidget.item;
import static org.junit.Assert.*;

/**
 * Tests the collection-log widget walker via MockWidget — we build a
 * tree that resembles what the real CL widget exposes (categories
 * containing items with quantities) and verify the extractor handles
 * every edge case: nested categories, zero-quantity items, items
 * already seen on a previous extraction.
 */
public class CollectionLogReaderTest {

    @Test
    public void extractsObtainedItems() {
        // Two raid uniques + one unowned item + a nested "Bosses" tab
        // with one more obtained item.
        CollectionLogReader.MockWidget tree = container(
            container(
                item(20997, 1), // Twisted bow
                item(22325, 2), // Scythe of vitur (2 obtained)
                item(27275, 0)  // Tumeken's shadow — not obtained
            ),
            container(
                item(21907, 1)  // Vorkath's head
            )
        );

        List<Integer> obtained = CollectionLogReader.extractFromMock(tree);
        assertEquals(3, obtained.size());
        assertTrue(obtained.contains(20997));
        assertTrue(obtained.contains(22325));
        assertTrue(obtained.contains(21907));
        assertFalse("zero-qty item should not be marked obtained", obtained.contains(27275));
    }

    @Test
    public void deepNestingDoesntBreakExtraction() {
        // Five levels deep — CL widget tree can be at least this deep.
        CollectionLogReader.MockWidget deep =
            container(container(container(container(container(item(20997, 1))))));
        List<Integer> obtained = CollectionLogReader.extractFromMock(deep);
        assertEquals(1, obtained.size());
        assertTrue(obtained.contains(20997));
    }

    @Test
    public void emptyTreeReturnsEmpty() {
        CollectionLogReader.MockWidget tree = container();
        List<Integer> obtained = CollectionLogReader.extractFromMock(tree);
        assertTrue(obtained.isEmpty());
    }

    @Test
    public void mockStatusDistinguishesOpenedFromLoadedItemSlots() {
        CollectionLogReader.Status notOpened = CollectionLogReader.statusFromMock(null);
        CollectionLogReader.Status openedEmpty = CollectionLogReader.statusFromMock(container());
        CollectionLogReader.Status openedWithItems = CollectionLogReader.statusFromMock(container(
            item(20997, 0),
            item(22325, 1)
        ));

        assertFalse(notOpened.opened);
        assertFalse(notOpened.hasLoadedItemSlots());
        assertTrue(openedEmpty.opened);
        assertFalse(openedEmpty.hasLoadedItemSlots());
        assertEquals(0, openedEmpty.lastWidgetItemCount);
        assertTrue(openedWithItems.opened);
        assertTrue(openedWithItems.hasLoadedItemSlots());
        assertEquals(2, openedWithItems.lastWidgetItemCount);
        assertEquals(1, openedWithItems.obtainedItemCount);
    }

    @Test
    public void playerInstructionAvoidsWidgetJargon() {
        assertEquals(
            "Open Collection Log once, then sync again.",
            CollectionLogReader.playerInstruction(CollectionLogReader.Status.notOpened())
        );
        assertEquals(
            "Click a Collection Log category, then sync again.",
            CollectionLogReader.playerInstruction(new CollectionLogReader.Status(true, 1, 0, 0))
        );
        assertEquals(
            "Collection Log synced.",
            CollectionLogReader.playerInstruction(new CollectionLogReader.Status(true, 1, 12, 3))
        );
    }

    @Test
    public void duplicateItemsAcrossCategoriesAppearOnce() {
        // OSRS does sometimes list the same item under multiple
        // categories (cape from achievement + cape from skilling).
        // Should appear only once in the obtained list.
        CollectionLogReader.MockWidget tree = container(
            container(item(20997, 1)),
            container(item(20997, 1)), // same id again
            container(item(22325, 1))
        );
        List<Integer> obtained = CollectionLogReader.extractFromMock(tree);
        assertEquals(2, obtained.size());
    }

    @Test
    public void readerSingletonAccumulatesAcrossIngests() {
        // The plugin holds one reader per session. Each WidgetLoaded
        // event calls ingest() — items should accumulate, not replace.
        CollectionLogReader reader = new CollectionLogReader();

        // Mocking the live Widget API requires constructing real Widget
        // instances which we can't do in unit tests. Use the static
        // extractInto path with a real Set to verify the accumulator
        // logic — same code that ingest() uses internally.
        java.util.Set<Integer> session = new java.util.HashSet<>();
        CollectionLogReader.MockWidget first = container(item(20997, 1));
        CollectionLogReader.MockWidget second = container(item(22325, 1));

        // Direct extractMockInto isn't public; emulate via extractFromMock
        // and merge as the plugin would.
        session.addAll(CollectionLogReader.extractFromMock(first));
        session.addAll(CollectionLogReader.extractFromMock(second));

        assertEquals(2, session.size());
        assertTrue(session.contains(20997));
        assertTrue(session.contains(22325));
    }

    @Test
    public void resetClearsCollectionLogStatus() {
        CollectionLogReader reader = new CollectionLogReader();

        assertFalse(reader.status().opened);
        reader.reset();
        assertFalse(reader.status().opened);
        assertEquals(0, reader.status().widgetLoads);
        assertEquals(0, reader.status().lastWidgetItemCount);
        assertEquals(0, reader.status().obtainedItemCount);
    }
}

package app.scapestack.runelite;

import org.junit.Test;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
