        ExternalPluginManager.loadBuiltin(ScapestackSyncPlugin.class);
        RuneLite.main(args);
    }
}

package app.scapestack.runelite;

import net.runelite.client.config.ConfigManager;

import java.util.UUID;

/**
 * Per-install secret used to bind a RuneLite installation to an RSN.
 *
 * Lifecycle:
 *   1. First plugin run: generate a UUID, persist via ConfigManager under
 *      ("scapestackSync", "installToken").
 *   2. Plugin's first sync POSTs {rsn} plus Authorization: Bearer <token>
 *      to /api/sync/claim. The server stores sha256(token) keyed by RSN,
 *      first-write-wins.
 *   3. Every subsequent /api/sync POST carries Authorization: Bearer <token>.
 *      Server rejects when the hash doesn't match the bound claim.
 *
 * The token is generated client-side so we never have to ship a secret
 * through any out-of-band channel; only this install knows it.
 *
 * Threat model + caveats live in src/lib/sync-auth.ts on the server side.
 *
 * Test seam: the bottom-half helpers accept a {@link KeyValueStore} so
 * unit tests can substitute an in-memory map for ConfigManager (which
 * needs a full RuneLite DI context to instantiate). The public overloads
 * adapt ConfigManager → KeyValueStore so plugin code stays unchanged.
 */
public final class InstallToken {

    private static final String GROUP = "scapestackSync";
    private static final String KEY_TOKEN   = "installToken";
    private static final String KEY_CLAIMED = "claimedRsn";

    private InstallToken() {}

    /** Anything that can persist {key → string-value} pairs. */
    public interface KeyValueStore {
        String get(String key);
        void set(String key, String value);
    }

    /** Wraps a ConfigManager so the plugin call-sites need no changes. */
    static KeyValueStore wrap(ConfigManager cm) {
        return new KeyValueStore() {
            @Override public String get(String key) {
                return cm.getConfiguration(GROUP, key);
            }
            @Override public void set(String key, String value) {
                cm.setConfiguration(GROUP, key, value);
            }
        };
    }

    // ---------- public API used by ScapestackSyncPlugin ----------

    public static String getOrCreate(ConfigManager cm)          { return getOrCreate(wrap(cm)); }
    public static String claimedRsn(ConfigManager cm)           { return claimedRsn(wrap(cm)); }
    public static void rememberClaimedRsn(ConfigManager cm, String rsn) { rememberClaimedRsn(wrap(cm), rsn); }
    public static void forgetClaim(ConfigManager cm)            { forgetClaim(wrap(cm)); }

    // ---------- test-facing overloads ----------

    public static String getOrCreate(KeyValueStore store) {
        String existing = store.get(KEY_TOKEN);
        if (existing != null && !existing.isBlank()) {
            return existing.trim();
        }
        String fresh = UUID.randomUUID().toString();
        store.set(KEY_TOKEN, fresh);
        return fresh;
    }

    public static String claimedRsn(KeyValueStore store) {
        String v = store.get(KEY_CLAIMED);
        return v == null || v.isBlank() ? null : v.trim();
    }

    public static void rememberClaimedRsn(KeyValueStore store, String rsn) {
        store.set(KEY_CLAIMED, rsn);
    }

    public static void forgetClaim(KeyValueStore store) {
        store.set(KEY_CLAIMED, "");
    }
}

package app.scapestack.runelite;

import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import java.io.IOException;

/** Approves a short browser pairing code using the existing install claim. */
@Slf4j
final class PairingClient {
    private static final MediaType JSON = MediaType.parse("application/json");
    private final OkHttpClient http;

    PairingClient(OkHttpClient http) {
        this.http = http;
    }

    boolean approve(String syncUrl, String rsn, String code, String token, String userAgent) {
        JsonObject body = new JsonObject();
        body.addProperty("rsn", rsn);
        body.addProperty("code", normalizeCode(code));
        try {
            Request request = new Request.Builder()
                .url(pairingUrlFromSyncUrl(syncUrl))
                .post(RequestBody.create(JSON, body.toString()))
                .header("User-Agent", userAgent)
                .header("Authorization", "Bearer " + token)
                .build();
            try (Response response = http.newCall(request).execute()) {
                String responseBody = ServerResponseSummary.readBody(response);
                if (response.isSuccessful()) return true;
                log.warn("Scapestack browser connection failed: {}",
                    ServerResponseSummary.logDetail(response.code(), responseBody));
                return false;
            }
        } catch (IllegalArgumentException ex) {
            log.warn("Scapestack browser connection URL is invalid");
            return false;
        } catch (IOException ex) {
            log.warn("Scapestack browser connection request failed", ex);
            return false;
        }
    }

    static String normalizeCode(String code) {
        if (code == null) return "";
        String clean = code.toUpperCase().replaceAll("[^A-Z0-9]", "");
        return clean.substring(0, Math.min(8, clean.length()));
    }

    static String pairingUrlFromSyncUrl(String syncUrl) {
        String clean = ClaimClient.normalizeSyncUrl(syncUrl);
        if (clean.endsWith("/api/sync")) {
            return clean.substring(0, clean.length() - "/api/sync".length()) + "/api/account/pair/approve";
        }
        if (clean.endsWith("/sync")) {
            return clean.substring(0, clean.length() - "/sync".length()) + "/account/pair/approve";
        }
        return clean + "/account/pair/approve";
    }
}

package app.scapestack.runelite;

import com.google.gson.JsonObject;

import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Versioned metadata that keeps missing RuneLite domains explicit. */
final class PluginSnapshotContract {
    static final int VERSION = 3;
    static final List<String> DOMAINS = Arrays.asList(
        "skills",
        "quests",
        "diaries",
        "collectionLog",
        "bossKc",
        "slayer",
        "accountMode",
        "bank"
    );

    static final class Domain {
        final String state;
        final String capturedAt;
        final String reason;

        Domain(String state, String capturedAt, String reason) {
            this.state = state;
            this.capturedAt = capturedAt;
            this.reason = reason;
        }

        static Domain available(String capturedAt) {
            return available(capturedAt, null);
        }

        static Domain available(String capturedAt, String reason) {
            return new Domain("available", validTimestamp(capturedAt), reason);
        }

        static Domain unavailable(String reason) {
            return new Domain("unavailable", null, reason);
        }

        static Domain permissionOff(String reason) {
            return new Domain("permission-off", null, reason);
        }

        static Domain notLoaded(String reason) {
            return new Domain("not-loaded", null, reason);
        }

        static Domain unsupported(String reason) {
            return new Domain("unsupported", null, reason);
        }
    }

    private PluginSnapshotContract() {}

    static Map<String, Domain> observedCoverage(GameStateReader.Snapshot snapshot) {
        String capturedAt = validTimestamp(snapshot.capturedAt);
        Map<String, Domain> coverage = new LinkedHashMap<>();
        coverage.put("skills", snapshot.skills != null && !snapshot.skills.isEmpty()
            ? Domain.available(capturedAt)
            : Domain.unavailable("skills-unavailable"));
        coverage.put("quests", Domain.available(capturedAt));
        coverage.put("diaries", Domain.available(capturedAt));

        CollectionLogReader.Status collectionLog = snapshot.collectionLogStatus;
        if (collectionLog != null && collectionLog.hasLoadedItemSlots()) {
            coverage.put("collectionLog", Domain.available(
                firstTimestamp(collectionLog.capturedAt, capturedAt),
                "loaded-categories-only"
            ));
        } else if (collectionLog != null && collectionLog.opened) {
            coverage.put("collectionLog", Domain.notLoaded("collection-log-category-not-loaded"));
        } else {
            coverage.put("collectionLog", Domain.notLoaded("collection-log-not-opened"));
        }

        coverage.put("bossKc", bossKcCoverage(snapshot, capturedAt));
        coverage.put("slayer", snapshot.slayer != null
            ? Domain.available(capturedAt)
            : Domain.unavailable("slayer-vars-unavailable"));
        coverage.put("accountMode", snapshot.accountType != null && !snapshot.accountType.isBlank()
            ? Domain.available(capturedAt)
            : Domain.unavailable("account-mode-unavailable"));
        coverage.put("bank", bankCoverage(snapshot, capturedAt));
        return coverage;
    }

    static Map<String, Domain> completeCoverage(GameStateReader.Snapshot snapshot) {
        Map<String, Domain> coverage = observedCoverage(snapshot);
        if (snapshot.coverage != null) {
            for (String domain : DOMAINS) {
                Domain explicit = snapshot.coverage.get(domain);
                if (explicit != null) coverage.put(domain, explicit);
            }
        }
        return coverage;
    }

    static JsonObject coverageJson(GameStateReader.Snapshot snapshot) {
        JsonObject result = new JsonObject();
        for (Map.Entry<String, Domain> entry : completeCoverage(snapshot).entrySet()) {
            Domain domain = entry.getValue();
            JsonObject row = new JsonObject();
            row.addProperty("state", domain.state);
            if (domain.capturedAt != null) row.addProperty("capturedAt", domain.capturedAt);
            if (domain.reason != null && !domain.reason.isBlank()) row.addProperty("reason", domain.reason);
            result.add(entry.getKey(), row);
        }
        return result;
    }

    private static Domain bankCoverage(GameStateReader.Snapshot snapshot, String fallbackCapturedAt) {
        GameStateReader.BankStatus status = snapshot.bankStatus;
        if (status == null) return Domain.unavailable("bank-status-unavailable");
        if (!status.enabled && snapshot.bankItems != null && !snapshot.bankItems.isEmpty()) {
            return Domain.available(fallbackCapturedAt);
        }
        if (!status.enabled) return Domain.permissionOff("bank-sync-disabled");
        if ("bank-not-opened-this-session".equals(status.unavailableReason)) {
            return Domain.notLoaded("bank-not-opened-this-session");
        }
        if (status.unavailableReason != null && !status.unavailableReason.isBlank()) {
            return Domain.unavailable(status.unavailableReason);
        }
        return Domain.available(firstTimestamp(status.capturedAt, fallbackCapturedAt));
    }

    private static Domain bossKcCoverage(GameStateReader.Snapshot snapshot, String fallbackCapturedAt) {
        BossKillCountReader.Result status = snapshot.bossKcStatus;
        if (status == null) {
            return snapshot.bossKc != null
                ? Domain.available(fallbackCapturedAt, "observed-boss-kill-counts")
                : Domain.notLoaded("boss-kill-counts-not-read");
        }
        if ("available".equals(status.state)) {
            return Domain.available(firstTimestamp(status.capturedAt, fallbackCapturedAt), status.reason);
        }
        if ("not-loaded".equals(status.state)) {
            return Domain.notLoaded(status.reason);
        }
        return Domain.unavailable(status.reason);
    }

    private static String firstTimestamp(String preferred, String fallback) {
        String validPreferred = validTimestamp(preferred);
        return validPreferred != null ? validPreferred : validTimestamp(fallback);
    }

    private static String validTimestamp(String value) {
        if (value == null || value.isBlank()) return null;
        try {
            return Instant.parse(value).toString();
        } catch (DateTimeParseException ignored) {
            return null;
        }
    }
}

package app.scapestack.runelite;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import java.io.IOException;
import java.util.function.Consumer;

@Slf4j
final class SyncServiceReadiness {

    static final class Result {
        final boolean proceed;
        final String message;

        private Result(boolean proceed, String message) {
            this.proceed = proceed;
            this.message = message;
        }

        static Result proceed(String message) {
            return new Result(true, message);
        }

        static Result stop(String message) {
            return new Result(false, message);
        }
    }

    private final OkHttpClient http;

    SyncServiceReadiness(OkHttpClient http) {
        this.http = http;
    }

    Result check(String syncUrl, String userAgent) {
        return check(syncUrl, userAgent, null);
    }

    Result check(String syncUrl, String userAgent, Consumer<Call> activeCall) {
        Request request;
        try {
            request = new Request.Builder()
                .url(syncUrl)
                .get()
                .header("User-Agent", userAgent)
                .build();
        } catch (IllegalArgumentException ex) {
            return Result.stop("invalid Sync URL");
        }

        Call call = http.newCall(request);
        updateActiveCall(activeCall, call);
        try (Response response = call.execute()) {
            String body = ServerResponseSummary.readBody(response);
            if (!response.isSuccessful()) {
                log.debug("Scapestack readiness check returned {}", response.code());
                return Result.proceed("readiness check skipped");
            }
            return parse(body);
        } catch (IOException ex) {
            log.debug("Scapestack readiness check failed", ex);
            return Result.proceed("readiness check unavailable");
        } finally {
            updateActiveCall(activeCall, null);
        }
    }

    private static void updateActiveCall(Consumer<Call> activeCall, Call call) {
        if (activeCall != null) {
            activeCall.accept(call);
        }
    }

    static Result parse(String body) {
        if (body == null || body.isBlank()) return Result.proceed("readiness check empty");
        try {
            JsonElement parsed = new JsonParser().parse(body);
            if (!parsed.isJsonObject()) return Result.proceed("readiness check ignored");
            JsonObject object = parsed.getAsJsonObject();
            JsonElement ready = object.get("ready");
            if (ready == null || !ready.isJsonPrimitive() || !ready.getAsJsonPrimitive().isBoolean()) {
                return Result.proceed("readiness check ignored");
            }
            if (ready.getAsBoolean()) return Result.proceed("service ready");
            return Result.stop(readinessFailureMessage(object));
        } catch (RuntimeException ex) {
            return Result.proceed("readiness check ignored");
        }
    }

    private static String readinessFailureMessage(JsonObject object) {
        JsonObject database = object.has("database") && object.get("database").isJsonObject()
            ? object.getAsJsonObject("database")
            : null;
        if (database == null) return "sync service is not ready";

        JsonElement configured = database.get("configured");
        if (configured != null && configured.isJsonPrimitive() && configured.getAsJsonPrimitive().isBoolean()
            && !configured.getAsBoolean()) {
            return "sync database is not configured";
        }

        JsonElement reason = database.get("reason");
        if (reason != null && reason.isJsonPrimitive()) {
            String text = reason.getAsString().trim();
            if (!text.isEmpty()) return text;
        }

        return "sync database schema is incomplete";
    }
}

package app.scapestack.runelite;

import java.util.concurrent.atomic.AtomicBoolean;

final class SyncGate {
    private final AtomicBoolean inFlight = new AtomicBoolean(false);

    boolean tryStart() {
        return inFlight.compareAndSet(false, true);
    }

    void finish() {
        inFlight.set(false);
    }

    boolean isInFlight() {
        return inFlight.get();
    }
}

package app.scapestack.runelite;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** Reads only boss counts that RuneLite has actually observed for this profile. */
final class BossKillCountReader {
    static final int MAX_BOSSES = 128;
    private static final int MAX_BOSS_NAME_LENGTH = 80;
    private static final String CONFIG_GROUP = "killcount";

    @FunctionalInterface
    interface KillCountLookup {
        Integer get(String key) throws Exception;
    }

    static final class Result {
        final String state;
        final Map<String, Integer> counts;
        final int knownBosses;
        final int catalogBosses;
        final String capturedAt;
        final String reason;

        private Result(
            String state,
            Map<String, Integer> counts,
            int knownBosses,
            int catalogBosses,
            String capturedAt,
            String reason
        ) {
            this.state = state;
            this.counts = counts == null
                ? Collections.emptyMap()
                : Collections.unmodifiableMap(new LinkedHashMap<>(counts));
            this.knownBosses = knownBosses;
            this.catalogBosses = catalogBosses;
            this.capturedAt = capturedAt;
            this.reason = reason;
        }

        static Result available(
            Map<String, Integer> counts,
            int catalogBosses,
            String capturedAt,
            int lookupFailures
        ) {
            int knownBosses = counts != null ? counts.size() : 0;
            String reason = lookupFailures > 0
                ? "runelite-killcount-cache-partial"
                : "runelite-killcount-cache-observed-only";
            return new Result("available", counts, knownBosses, catalogBosses, capturedAt, reason);
        }

        static Result notLoaded(int catalogBosses, String reason) {
            return new Result("not-loaded", null, 0, catalogBosses, null, reason);
        }

        static Result unavailable(String reason) {
            return new Result("unavailable", null, 0, 0, null, reason);
        }

        boolean isAvailable() {
            return "available".equals(state);
        }
    }

    private BossKillCountReader() {}

    static Result read(ConfigManager configManager, String capturedAt) {
        if (configManager == null) {
            return Result.unavailable("boss-killcount-cache-unavailable");
        }

        List<String> bossNames = defaultBossCatalog();
        if (bossNames.isEmpty()) {
            return Result.unavailable("boss-catalog-unavailable");
        }

        return readObservedCounts(
            bossNames,
            key -> configManager.getRSProfileConfiguration(CONFIG_GROUP, key, Integer.TYPE),
            capturedAt
        );
    }

    static Result readObservedCounts(
        List<String> bossNames,
        KillCountLookup lookup,
        String capturedAt
    ) {
        List<String> catalog = normalizeCatalog(bossNames);
        if (catalog.isEmpty()) {
            return Result.unavailable("boss-catalog-unavailable");
        }
        if (lookup == null) {
            return Result.unavailable("boss-killcount-cache-unavailable");
        }

        Map<String, Integer> counts = new LinkedHashMap<>();
        int lookupFailures = 0;
        for (String name : catalog) {
            Integer count;
            try {
                count = lookup.get(name.toLowerCase(Locale.ROOT));
            } catch (Exception ignored) {
                lookupFailures++;
                continue;
            }
            if (count == null) continue;
            if (count < 0) {
                lookupFailures++;
                continue;
            }
            counts.put(name, count);
        }

        if (counts.isEmpty()) {
            if (lookupFailures >= catalog.size()) {
                return Result.unavailable("boss-killcount-cache-unavailable");
            }
            return Result.notLoaded(catalog.size(), "boss-kill-log-not-observed");
        }
        return Result.available(counts, catalog.size(), capturedAt, lookupFailures);
    }

    static List<String> defaultBossCatalog() {
        List<String> names = new ArrayList<>();
        for (HiscoreSkill skill : HiscoreSkill.values()) {
            if (skill.getType() != HiscoreSkillType.BOSS) continue;
            names.add(skill.getName());
            if (names.size() >= MAX_BOSSES) break;
        }
        return normalizeCatalog(names);
    }

    private static List<String> normalizeCatalog(List<String> bossNames) {
        if (bossNames == null || bossNames.isEmpty()) return Collections.emptyList();
        Set<String> seen = new LinkedHashSet<>();
        List<String> normalized = new ArrayList<>();
        for (String rawName : bossNames) {
            if (normalized.size() >= MAX_BOSSES) break;
            if (rawName == null) continue;
            String name = rawName.trim();
            if (name.isEmpty() || name.length() > MAX_BOSS_NAME_LENGTH) continue;
            String key = name.toLowerCase(Locale.ROOT);
            if (seen.add(key)) normalized.add(name);
        }
        return normalized;
    }
}

package app.scapestack.runelite;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.widgets.Widget;

import javax.inject.Singleton;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Scrapes the Collection Log widget when the player opens it.
 *
 * The CL widget is layered: a top-level "tabs" widget (Bosses / Raids /
 * Clues / Minigames / Other), each tab has "category" widgets (e.g.
 * "Chambers of Xeric"), and each category has an "items" widget
 * containing every possible drop with a quantity (0 = not obtained).
 *
 * We snapshot the union of obtained-item-IDs across every category the
 * widget has loaded. The player has to open the log once per session
 * for full data — RuneLite memory only holds what was actually rendered.
 *
 * State is held in memory by the plugin between syncs. Each time a new
 * CL category loads we merge it in. On sync we emit the current union.
 *
 * Like DiaryReader, the parsing logic is pure-function-on-widget-data
 * so it tests without a live game client. The plugin calls
 * extractObtainedItems(rootWidget); the test calls extractFromMock.
 */
@Slf4j
@Singleton
public class CollectionLogReader {

    // In-memory accumulator. Cleared per-login by the plugin so a
    // stale account doesn't leak between players sharing a client.
    private final Set<Integer> obtainedItemIds = new HashSet<>();
    private int widgetLoadCount;
    private int lastWidgetItemCount;
    private String lastCapturedAt;

    public synchronized void reset() {
        obtainedItemIds.clear();
        widgetLoadCount = 0;
        lastWidgetItemCount = 0;
        lastCapturedAt = null;
    }

    public synchronized List<Integer> snapshot() {
        return new ArrayList<>(obtainedItemIds);
    }

    public synchronized Status status() {
        return new Status(
            widgetLoadCount > 0,
            widgetLoadCount,
            lastWidgetItemCount,
            obtainedItemIds.size(),
            lastCapturedAt
        );
    }

    /**
     * Called when the Collection Log widget loads. Walks every
     * descendant looking for item-quantity pairs and adds anything
     * with quantity > 0.
     *
     * Widget structure in OSRS (community-documented):
     *   - Each "item" leaf widget has getItemId() and getItemQuantity()
     *   - Quantity 0 == not obtained yet
     *   - Quantity > 0 == player has at least one
     */
    public synchronized int ingest(Widget rootWidget) {
        if (rootWidget == null) return 0;
        widgetLoadCount++;
        lastWidgetItemCount = countItemWidgets(rootWidget);
        lastCapturedAt = Instant.now().toString();
        return extractInto(rootWidget, obtainedItemIds);
    }

    private static int countItemWidgets(Widget root) {
        if (root == null) return 0;
        int count = root.getItemId() > 0 ? 1 : 0;
        Widget[] children = root.getDynamicChildren();
        if (children != null) {
            for (Widget c : children) {
                count += countItemWidgets(c);
            }
        }
        Widget[] statics = root.getStaticChildren();
        if (statics != null) {
            for (Widget c : statics) {
                count += countItemWidgets(c);
            }
        }
        return count;
    }

    /**
     * Pure-data extractor that walks the widget tree depth-first and
     * adds every item-with-quantity-> 0 to the destination set.
     * Returns the count added in this call.
     */
    public static int extractInto(Widget root, Set<Integer> dst) {
        int added = 0;
        Widget[] children = root.getDynamicChildren();
        if (children != null) {
            for (Widget c : children) {
                added += extractInto(c, dst);
            }
        }
        Widget[] statics = root.getStaticChildren();
        if (statics != null) {
            for (Widget c : statics) {
                added += extractInto(c, dst);
            }
        }
        // Leaf check: item-widgets have a positive itemId AND a non-
        // zero quantity. The 'quantity' here is OSRS's collection-log
        // count, not a stack size from a bank.
        int itemId = root.getItemId();
        int qty = root.getItemQuantity();
        if (itemId > 0 && qty > 0 && !dst.contains(itemId)) {
            dst.add(itemId);
            added++;
        }
        return added;
    }

    /**
     * Test-friendly variant taking a fake widget tree. Tests can build
     * MockWidget instances and feed them in; we still exercise the
     * exact extract path the live code uses.
     */
    public static List<Integer> extractFromMock(MockWidget root) {
        Set<Integer> dst = new HashSet<>();
        extractMockInto(root, dst);
        return new ArrayList<>(dst);
    }

    public static Status statusFromMock(MockWidget root) {
        return new Status(
            root != null,
            root == null ? 0 : 1,
            countMockItemWidgets(root),
            extractFromMock(root).size(),
            root == null ? null : Instant.now().toString()
        );
    }

    public static String playerInstruction(Status status) {
        if (status == null || !status.opened) {
            return "Open Collection Log once, then sync again.";
        }
        if (!status.hasLoadedItemSlots()) {
            return "Click a Collection Log category, then sync again.";
        }
        return "Collection Log synced.";
    }

    private static int countMockItemWidgets(MockWidget root) {
        if (root == null) return 0;
        int count = root.itemId > 0 ? 1 : 0;
        for (MockWidget c : root.children) {
            count += countMockItemWidgets(c);
        }
        return count;
    }

    private static void extractMockInto(MockWidget root, Set<Integer> dst) {
        if (root == null) return;
        for (MockWidget c : root.children) extractMockInto(c, dst);
        if (root.itemId > 0 && root.quantity > 0) dst.add(root.itemId);
    }

    /**
     * Lightweight stand-in for Widget that we can build in tests.
     * Only carries the three things extractInto needs: children, itemId,
     * and quantity. The real Widget has 100+ methods we don't need.
     */
    public static final class MockWidget {
        public final int itemId;
        public final int quantity;
        public final List<MockWidget> children;

        public MockWidget(int itemId, int quantity, MockWidget... children) {
            this.itemId = itemId;
            this.quantity = quantity;
            this.children = children == null ? Collections.emptyList() : new ArrayList<>(java.util.Arrays.asList(children));
        }

        public static MockWidget container(MockWidget... children) {
            return new MockWidget(0, 0, children);
        }

        public static MockWidget item(int itemId, int quantity) {
            return new MockWidget(itemId, quantity);
        }
    }

    public static final class Status {
        public final boolean opened;
        public final int widgetLoads;
        public final int lastWidgetItemCount;
        public final int obtainedItemCount;
        public final String capturedAt;

        public Status(boolean opened, int widgetLoads, int lastWidgetItemCount, int obtainedItemCount) {
            this(opened, widgetLoads, lastWidgetItemCount, obtainedItemCount, null);
        }

        public Status(boolean opened, int widgetLoads, int lastWidgetItemCount, int obtainedItemCount, String capturedAt) {
            this.opened = opened;
            this.widgetLoads = widgetLoads;
            this.lastWidgetItemCount = lastWidgetItemCount;
            this.obtainedItemCount = obtainedItemCount;
            this.capturedAt = capturedAt;
        }

        public static Status notOpened() {
            return new Status(false, 0, 0, 0, null);
        }

        public boolean hasLoadedItemSlots() {
            return opened && lastWidgetItemCount > 0;
        }
    }
}

package app.scapestack.runelite;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * Static table mapping each diary region+tier to its OSRS VarPlayer ID
 * and a "completion mask" — the bit pattern the var holds when that tier
 * is fully done.
 *
 * Why VarPlayers instead of widget scraping:
 *   - VarPlayers are the source of truth in the game's data model;
 *     widgets only show what the var says.
 *   - Reading vars works regardless of whether the diary widget has
 *     ever been opened.
 *   - The mapping is documented on the Wiki ("Diary task tracking"
 *     section) and changes only when Jagex adds new diary content.
 *
 * Why a single mask per tier: in OSRS each diary task is one bit in the
 * region's var. "Tier complete" = "every task-bit in that tier is set."
 * The exact bit positions per tier come from the Wiki — we encode the
 * sum-of-bits expected for each tier as a mask. Reading
 * (varValue & mask) == mask is enough.
 *
 * NOTE: these IDs were sourced from the OSRS Wiki "Achievement diary"
 * data tables (May 2026 snapshot). Some recent additions may move; if
 * a tier never reads as done, the mask is the most likely culprit.
 * Keep this file in sync with the website's data/diaries.json regions.
 */
public final class DiaryVarTable {

    private DiaryVarTable() {}

    public enum Tier { EASY, MEDIUM, HARD, ELITE }

    public static final class Entry {
        public final String region;
        public final Tier tier;
        public final int varbitOrVar; // see isVarbit
        public final boolean isVarbit;
        public final int completedValue; // value the var/varbit holds when the tier is complete

        public Entry(String region, Tier tier, int id, boolean isVarbit, int completedValue) {
            this.region = region;
            this.tier = tier;
            this.varbitOrVar = id;
            this.isVarbit = isVarbit;
            this.completedValue = completedValue;
        }
    }

    /**
     * Each diary in OSRS has FOUR booleans (one per tier) that flip to 1
     * when that tier is complete. These flags are tracked by varbits. The
     * IDs below come from the open-source RuneLite QuestHelper plugin's
     * AchievementDiaries.java — the canonical reference in the
     * RuneLite community for diary-completion varbits.
     *
     * If any varbit ID has shifted (rare; Jagex usually appends), the
     * symptom is "tier never reads as done." Update from the Wiki's
     * "Varbit reference" page or QuestHelper's source.
     */
    public static final List<Entry> ENTRIES = Collections.unmodifiableList(Arrays.asList(
        // Ardougne
        new Entry("Ardougne",  Tier.EASY,   4458, true, 1),
        new Entry("Ardougne",  Tier.MEDIUM, 4459, true, 1),
        new Entry("Ardougne",  Tier.HARD,   4460, true, 1),
        new Entry("Ardougne",  Tier.ELITE,  4461, true, 1),
