        new Entry("Desert",    Tier.HARD,   4485, true, 1),
        new Entry("Desert",    Tier.ELITE,  4486, true, 1),
        // Falador
        new Entry("Falador",   Tier.EASY,   4504, true, 1),
        new Entry("Falador",   Tier.MEDIUM, 4505, true, 1),
        new Entry("Falador",   Tier.HARD,   4506, true, 1),
        new Entry("Falador",   Tier.ELITE,  4507, true, 1),
        // Fremennik
        new Entry("Fremennik", Tier.EASY,   4524, true, 1),
        new Entry("Fremennik", Tier.MEDIUM, 4525, true, 1),
        new Entry("Fremennik", Tier.HARD,   4526, true, 1),
        new Entry("Fremennik", Tier.ELITE,  4527, true, 1),
        // Kandarin
        new Entry("Kandarin",  Tier.EASY,   4546, true, 1),
        new Entry("Kandarin",  Tier.MEDIUM, 4547, true, 1),
        new Entry("Kandarin",  Tier.HARD,   4548, true, 1),
        new Entry("Kandarin",  Tier.ELITE,  4549, true, 1),
        // Karamja — varplayers (different shape: numeric milestone)
        new Entry("Karamja",   Tier.EASY,   3578, false, 5),
        new Entry("Karamja",   Tier.MEDIUM, 3599, false, 5),
        new Entry("Karamja",   Tier.HARD,   3611, false, 5),
        new Entry("Karamja",   Tier.ELITE,  4566, true, 1),
        // Kourend & Kebos
        new Entry("Kourend & Kebos", Tier.EASY,   7925, true, 1),
        new Entry("Kourend & Kebos", Tier.MEDIUM, 7926, true, 1),
        new Entry("Kourend & Kebos", Tier.HARD,   7927, true, 1),
        new Entry("Kourend & Kebos", Tier.ELITE,  7928, true, 1),
        // Lumbridge & Draynor
        new Entry("Lumbridge & Draynor", Tier.EASY,   4585, true, 1),
        new Entry("Lumbridge & Draynor", Tier.MEDIUM, 4586, true, 1),
        new Entry("Lumbridge & Draynor", Tier.HARD,   4587, true, 1),
        new Entry("Lumbridge & Draynor", Tier.ELITE,  4588, true, 1),
        // Morytania
        new Entry("Morytania", Tier.EASY,   4609, true, 1),
        new Entry("Morytania", Tier.MEDIUM, 4610, true, 1),
        new Entry("Morytania", Tier.HARD,   4611, true, 1),
        new Entry("Morytania", Tier.ELITE,  4612, true, 1),
        // Varrock
        new Entry("Varrock",   Tier.EASY,   4630, true, 1),
        new Entry("Varrock",   Tier.MEDIUM, 4631, true, 1),
        new Entry("Varrock",   Tier.HARD,   4632, true, 1),
        new Entry("Varrock",   Tier.ELITE,  4633, true, 1),
        // Western Provinces
        new Entry("Western Provinces", Tier.EASY,   4653, true, 1),
        new Entry("Western Provinces", Tier.MEDIUM, 4654, true, 1),
        new Entry("Western Provinces", Tier.HARD,   4655, true, 1),
        new Entry("Western Provinces", Tier.ELITE,  4656, true, 1),
        // Wilderness
        new Entry("Wilderness", Tier.EASY,   4680, true, 1),
        new Entry("Wilderness", Tier.MEDIUM, 4681, true, 1),
        new Entry("Wilderness", Tier.HARD,   4682, true, 1),
        new Entry("Wilderness", Tier.ELITE,  4683, true, 1)
    ));

    public static String tierName(Tier t) {
        switch (t) {
            case EASY:   return "Easy";
            case MEDIUM: return "Medium";
            case HARD:   return "Hard";
            case ELITE:  return "Elite";
            default: throw new IllegalArgumentException();
        }
    }

    /**
     * Pure-data version of "is this entry complete?" that takes the var
     * value directly. Used by both the live game reader and the unit
     * tests — the latter feed mock values so we don't need a Client.
     */
    public static boolean isComplete(Entry entry, int observedValue) {
        // For varbits the completedValue is 1 (boolean). For Karamja's
        // varplayer-based tiers we look for "value >= completedValue"
        // because the var counts up through milestones — a player who's
        // moved past the completion threshold reads higher than 5.
        if (entry.isVarbit) {
            return observedValue == entry.completedValue;
        }
        return observedValue >= entry.completedValue;
    }

    /**
     * Subset of ENTRIES whose region matches one of the supplied
     * region names. Used to keep the reader honest when the website
     * adds a new region — we don't blindly include diaries the engine
     * doesn't know about.
     */
    public static List<Entry> forKnownRegions(java.util.Set<String> knownRegions) {
        List<Entry> out = new ArrayList<>();
        for (Entry e : ENTRIES) {
            if (knownRegions.contains(e.region)) out.add(e);
        }
        return out;
    }
}

package app.scapestack.runelite;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntUnaryOperator;

/**
 * Pulls diary completion state out of the live game client by walking
 * the DiaryVarTable and reading each entry's varbit/varplayer value.
 *
 * Logic split: the reader is one class, the lookup table is another.
 * Tests instantiate the reader with a mock value-source (an
 * IntUnaryOperator that returns whatever the test supplies for each
 * id) so we never need a Client.
 */
@Slf4j
@Singleton
public class DiaryReader {

    /** Reads varbit IDs (the common case) and a few legacy varplayers. */
    public List<GameStateReader.DiaryCompletion> read(Client client) {
        return readFrom((id) -> {
            // VarPlayer IDs are typically < 5000; varbits often higher.
            // The table marks which is which.
            return tryRead(client, id);
        }, table -> table.isVarbit
            ? client.getVarbitValue(table.varbitOrVar)
            : client.getVarpValue(table.varbitOrVar));
    }

    private int tryRead(Client client, int id) {
        // Used by tests / fallbacks; real path goes through the BiFunction
        // overload below to keep varbit vs varplayer distinct.
        return client.getVarpValue(id);
    }

    /**
     * Test-friendly entry-point. Takes the resolver that knows how to
     * read a single DiaryVarTable.Entry — so tests can pass a mock
     * map and never construct a Client.
     */
    public List<GameStateReader.DiaryCompletion> readFrom(
            IntUnaryOperator legacyReader, // kept for back-compat with the live-Client path
            EntryReader entryReader) {
        List<GameStateReader.DiaryCompletion> out = new ArrayList<>();
        for (DiaryVarTable.Entry e : DiaryVarTable.ENTRIES) {
            int value;
            try {
                value = entryReader.read(e);
            } catch (Exception ex) {
                // A missing varbit/varplayer happens with stale Wiki data;
                // skip silently so one bad ID doesn't kill the whole sync.
                log.debug("Diary var read failed for {} {}: {}", e.region, e.tier, ex.getMessage());
                continue;
            }
            if (DiaryVarTable.isComplete(e, value)) {
                out.add(new GameStateReader.DiaryCompletion(e.region, DiaryVarTable.tierName(e.tier)));
            }
        }
        log.debug("Read {} completed diary tiers", out.size());
        return out;
    }

    @FunctionalInterface
    public interface EntryReader {
        int read(DiaryVarTable.Entry entry);
    }
}

package app.scapestack.runelite;

import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.MediaType;
import okhttp3.Call;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import java.io.IOException;
import java.net.URI;
import java.util.function.Consumer;

/**
 * Thin client for POST /api/sync/claim.
 *
 * Separate from the main sync POST because the claim is a one-shot per
 * (install, rsn) pair — once it succeeds we cache the RSN locally and
 * never call it again. Pulled out so {@link ScapestackSyncPlugin} stays
 * focused on the per-tick sync hot path.
 */
@Slf4j
public final class ClaimClient {

    private static final MediaType JSON = MediaType.parse("application/json");

    private final OkHttpClient http;

    public ClaimClient(OkHttpClient http) {
        this.http = http;
    }

    /**
     * POSTs the claim. Returns true on a 2xx response, false on anything
     * else. We treat the call as best-effort: a 409 (RSN already claimed
     * by another install) leaves the sync POST to fail with 403, which
     * the user will see in the log.
     *
     * The {@code claimUrl} is derived from the sync endpoint by replacing
     * the trailing /sync with /sync/claim — keeps one config field.
     */
    public boolean claim(String claimUrl, String rsn, String token, String userAgent) {
        return claim(claimUrl, rsn, token, userAgent, null);
    }

    boolean claim(String claimUrl, String rsn, String token, String userAgent, Consumer<Call> activeCall) {
        JsonObject body = new JsonObject();
        body.addProperty("rsn", rsn);

        try {
            Request req = new Request.Builder()
                .url(claimUrl)
                .post(RequestBody.create(JSON, body.toString()))
                .header("User-Agent", userAgent)
                .header("Authorization", "Bearer " + token)
                .build();
            Call call = http.newCall(req);
            updateActiveCall(activeCall, call);
            try (Response res = call.execute()) {
                String bodyText = ServerResponseSummary.readBody(res);
                if (res.isSuccessful()) {
                    log.info("Scapestack claim ok for {}", rsn);
                    return true;
                }
                log.warn("Scapestack claim failed for {}: {}",
                    rsn,
                    ServerResponseSummary.logDetail(res.code(), bodyText));
                return false;
            } finally {
                updateActiveCall(activeCall, null);
            }
        } catch (IllegalArgumentException ex) {
            log.warn("Scapestack claim URL is invalid: {}", claimUrl);
            return false;
        } catch (IOException ex) {
            log.warn("Scapestack claim request failed", ex);
            return false;
        }
    }

    private static void updateActiveCall(Consumer<Call> activeCall, Call call) {
        if (activeCall != null) {
            activeCall.accept(call);
        }
    }

    /**
     * Normalizes a user-configured sync endpoint before OkHttp sees it.
     * RuneLite config text fields are easy to paste with whitespace; query
     * strings and fragments also break claim URL derivation because the claim
     * route is path-based. Keep this conservative: trim, strip ?/# suffixes,
     * collapse trailing slashes, and recover when a user pasted the derived
     * /sync/claim endpoint instead of the base /sync endpoint.
     */
    public static String normalizeSyncUrl(String syncUrl) {
        if (syncUrl == null) return "";
        String clean = syncUrl.trim();
        int query = clean.indexOf('?');
        int fragment = clean.indexOf('#');
        int cut = -1;
        if (query >= 0) cut = query;
        if (fragment >= 0 && (cut < 0 || fragment < cut)) cut = fragment;
        if (cut >= 0) clean = clean.substring(0, cut);
        while (clean.endsWith("/") && !clean.endsWith("://")) {
            clean = clean.substring(0, clean.length() - 1);
        }
        if (clean.endsWith("/sync/claim")) {
            clean = clean.substring(0, clean.length() - "/claim".length());
        }
        return clean;
    }

    /**
     * Derives the claim endpoint URL from the configured sync URL.
     * Public for the unit test.
     */
    public static String claimUrlFromSyncUrl(String syncUrl) {
        String clean = normalizeSyncUrl(syncUrl);
        if (clean.isEmpty()) return "";
        if (clean.endsWith("/sync")) return clean + "/claim";
        return clean + "/claim";
    }

    /**
     * Returns true only for network endpoints OkHttp can POST to and the
     * plugin can safely echo back as a browser handoff origin.
     */
    public static boolean isHttpSyncUrl(String syncUrl) {
        String clean = normalizeSyncUrl(syncUrl);
        if (clean.isEmpty()) return false;
        try {
            URI uri = URI.create(clean);
            String scheme = uri.getScheme();
            return ("https".equalsIgnoreCase(scheme) || "http".equalsIgnoreCase(scheme))
                && uri.getHost() != null
                && !uri.getHost().isBlank();
        } catch (IllegalArgumentException ex) {
            return false;
        }
    }
}
